import{_ as i,q as r,o as l,c as h,b as e,k as t,j as s,y as d,m as c}from"./chunks/framework.D3-xQjZb.js";const y=JSON.parse('{"title":"Six Articles, One Witness","description":"See how a proposed graph and vector search system would follow a claim back to its origin, distinguish repeated testimony, and retain competing accounts.","frontmatter":{"title":"Six Articles, One Witness","description":"See how a proposed graph and vector search system would follow a claim back to its origin, distinguish repeated testimony, and retain competing accounts.","teaser":"A search returns six accounts of an event. If all six quote the same interview, how many independent witnesses should a briefing report?","articleGenre":"Research proposal and corpus case study"},"headers":[],"relativePath":"research/systems/provenance-knowledge-graphs.md","filePath":"research/systems/provenance-knowledge-graphs.md"}'),p={name:"research/systems/provenance-knowledge-graphs.md"};function u(m,a,f,g,w,v){const n=r("ArticleHeader"),o=r("ReaderTable");return l(),h("div",null,[a[1]||(a[1]=e("h1",{id:"from-messy-multimodal-sources-to-qualified-knowledge",tabindex:"-1"},[t("Six Articles, One Witness "),e("a",{class:"header-anchor",href:"#from-messy-multimodal-sources-to-qualified-knowledge","aria-label":'Permalink to "Six Articles, One Witness {#from-messy-multimodal-sources-to-qualified-knowledge}"'},"​")],-1)),s(n),a[2]||(a[2]=e("p",null,"A search interface returns six articles, each with a citation. Follow the links and every account leads to the same interview. The search did its job. The briefing writer still has to decide how much independent support the claim has.",-1)),a[3]||(a[3]=e("p",null,"This is the problem I want a knowledge graph to help solve. When a sentence moves from an archive to a summary and then into a report, the reader should still be able to tell who said it, on what basis, and whether anyone else observed it independently.",-1)),a[4]||(a[4]=e("p",null,[t("You can try the decision on paper in ten minutes. Read a fictional harbor log, a neighborhood bulletin, and a dispatch note. Before you look at the discussion notes, mark which lines support the claim that a light moved. How many people independently reported motion? "),e("a",{href:"/knowledge-lab/guide/walkthrough",target:"_self"},"Open the three-report exercise"),t(".")],-1)),a[5]||(a[5]=e("h2",{id:"separate-four-things",tabindex:"-1"},[t("Separate four things "),e("a",{class:"header-anchor",href:"#separate-four-things","aria-label":'Permalink to "Separate four things"'},"​")],-1)),s(o,{label:"Table: Separate four things"},{default:d(()=>[...a[0]||(a[0]=[e("table",null,[e("thead",null,[e("tr",null,[e("th",null,"Record"),e("th",null,"What to keep")])]),e("tbody",null,[e("tr",null,[e("td",null,"Source"),e("td",null,"Original file, access rights, content hash, and exact passage or time interval")]),e("tr",null,[e("td",null,"Observation"),e("td",null,"What a parser, sensor, or model extracted, its version, and the limits of the reading")]),e("tr",null,[e("td",null,"Candidate claim"),e("td",null,"The proposition, who made it, whose identity is uncertain, and the evidence for and against it")]),e("tr",null,[e("td",null,"Qualified claim"),e("td",null,"What an authorized reviewer or policy accepted, for which use, and why")])])],-1)])]),_:1}),a[6]||(a[6]=c('<p>“Include this statement in the testimony index” and “publish this assertion as established” grant different permissions. The record needs enough detail to tell which decision a reviewer actually made.</p><h2 id="why-a-hybrid-graph-and-vector-system" tabindex="-1">Why a hybrid graph and vector system <a class="header-anchor" href="#why-a-hybrid-graph-and-vector-system" aria-label="Permalink to &quot;Why a hybrid graph and vector system&quot;">​</a></h2><p>A vector search can find descriptions with similar meanings even when people use different words. Exact search can recover a case number or a particular spelling. A graph can connect six articles to the interview they share and preserve a seventh source that offers a different account.</p><p>I would retrieve the small set of relevant relationships, then return to the source passages. Compression makes an archive navigable. It can also remove a qualifier. A worthwhile evaluation should ask reviewers to find whichever caveat a summary left out.</p><h2 id="uap-corpus-as-a-difficult-case" tabindex="-1">UAP corpus as a difficult case <a class="header-anchor" href="#uap-corpus-as-a-difficult-case" aria-label="Permalink to &quot;UAP corpus as a difficult case&quot;">​</a></h2><p>The reviewed snapshot of my private UAP research catalog contains <strong>38 metadata records and leads</strong>. They include government archives, hearings, books, scientific papers, and first- or secondhand accounts. The original files had yet to be acquired. The proposed claim network is a design.</p><p>For a pilot, I would start with a small rights-cleared selection such as a government report and a hearing transcript. Label the event date separately from the dates of testimony and publication. Ask annotators which statements quote a witness, which restate another publication, and which supply independent observations. These labels let us score attribution and source copying even when the cause of an event is unknown.</p><h2 id="sensors-and-the-pit-stop" tabindex="-1">Sensors and the Pit Stop <a class="header-anchor" href="#sensors-and-the-pit-stop" aria-label="Permalink to &quot;Sensors and the Pit Stop&quot;">​</a></h2><p>One checker might flag a missing passage. Another might propose that two names refer to the same person. A third might discover that several articles repeat one interview. Each reports what it found. A separate policy determines whether a person needs to review the case, particularly for a sensitive allegation, a restricted source, or a proposed identity merge.</p><p>Also check a sample of cases that <em>didn’t</em> trigger review. A system that catches errors only when its own detector raises a flag can remain unaware of a systematic mistake.</p><h2 id="literature-and-open-questions" tabindex="-1">Literature and open questions <a class="header-anchor" href="#literature-and-open-questions" aria-label="Permalink to &quot;Literature and open questions&quot;">​</a></h2><p>Provenance standards already describe how one record derives from another. GraphRAG shows how to summarize collections using graphs. GRACE considers the return on expert attention in a graph of grounded claims. I want to test whether additional source checks and review rules preserve contradictions and improve attribution within a fixed review budget. <a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noreferrer">W3C PROV-O</a> · <a href="https://www.microsoft.com/en-us/research/publication/from-local-to-global-a-graph-rag-approach-to-query-focused-summarization/" target="_blank" rel="noreferrer">GraphRAG</a> · <a href="https://aclanthology.org/2026.akbc-1.16/" target="_blank" rel="noreferrer">GRACE</a></p><p><a href="./">Research series</a> · <a href="./dissertation-proposal">Dissertation proposal</a></p>',13))])}const k=i(p,[["render",u]]);export{y as __pageData,k as default};
